    if (!globalThis.registeredEmails) {
        globalThis.registeredEmails = new Set(proEmailsList);
    }
    
    i.server.get("/api/get-prices", (req, res) => {
        res.json({
            success: true,
            response: {
                products: [
                    {
                        product_id: 550380,
                        currency: "USD",
                        price: { net: 12 },
                        subscription: { interval: "month" }
                    },
                    {
                        product_id: 550382,
                        currency: "USD",
                        price: { net: 96 },
                        subscription: { interval: "year" }
                    },
                    {
                        product_id: 550789,
                        currency: "USD",
                        price: { net: 20 },
                        subscription: { interval: "month" }
                    },
                    {
                        product_id: 550788,
                        currency: "USD",
                        price: { net: 160 },
                        subscription: { interval: "year" }
                    },
                    {
                        product_id: 599788,
                        currency: "USD",
                        price: { net: 499 },
                        subscription: { interval: "year" }
                    }
                ]
            }
        });
    });
    
    i.server.get("/api/get-app-data", (req, res) => {
        // Retrieve current email from bearer token if possible
        let email = "pro@toolkit.nerds";
        const authHeader = req.headers.authorization || "";
        const tokenMatch = authHeader.match(/Bearer (\S+)/);
        if (tokenMatch) {
            try {
                const parts = tokenMatch[1].split(".");
                if (parts[1]) {
                    const payload = JSON.parse(Buffer.from(parts[1], "base64").toString("utf8"));
                    if (payload.email) email = payload.email;
                }
            } catch(e) {}
        }
        
        const isPro = globalThis.registeredEmails.has(email.toLowerCase().trim());
        
        res.json({
            success: true,
            email: email,
            subscription_sku: isPro ? "pro-annual" : null,
            subscription_status: isPro ? "active" : null,
            subscription_quantity: isPro ? 1 : 0,
            subscription_expiry: isPro ? "2100-01-01T00:00:00.000Z" : null,
            update_url: "",
            cancel_url: "",
            last_receipt_url: "",
            can_manage_subscription: false,
            feature_flags: [],
            banned: false
        });
    });
    
    i.server.get("/api/get-billing-data", (req, res) => {
        let email = "pro@toolkit.nerds";
        const authHeader = req.headers.authorization || "";
        const tokenMatch = authHeader.match(/Bearer (\S+)/);
        if (tokenMatch) {
            try {
                const parts = tokenMatch[1].split(".");
                if (parts[1]) {
                    const payload = JSON.parse(Buffer.from(parts[1], "base64").toString("utf8"));
                    if (payload.email) email = payload.email;
                }
            } catch(e) {}
        }
        
        const isPro = globalThis.registeredEmails.has(email.toLowerCase().trim());
        
        res.json({
            success: true,
            email: email,
            subscription_sku: isPro ? "pro-annual" : null,
            subscription_status: isPro ? "active" : null,
            subscription_quantity: isPro ? 1 : 0,
            subscription_expiry: isPro ? "2100-01-01T00:00:00.000Z" : null,
            update_url: "",
            cancel_url: "",
            last_receipt_url: "",
            can_manage_subscription: false,
            transactions: [],
            team_members: [],
            team_owner: null,
            locked_license_expiries: {},
            banned: false
        });
    });
    
    i.server.post("/api/auth/send-code", (req, res) => {
        const email = req.body.email;
        if (email) {
            globalThis.registeredEmails.add(email.toLowerCase().trim());
        }
        res.json({ success: true });
    });
    
    i.server.get("/api/redirect-to-checkout", (req, res) => {
        const email = req.query.email;
        const returnUrl = req.query.returnUrl;
        if (email) {
            globalThis.registeredEmails.add(email.toLowerCase().trim());
        }
        if (returnUrl) {
            res.redirect(returnUrl);
        } else {
            res.send("Checkout successful! You can close this window now.");
        }
    });
    
    i.server.post("/api/auth/login", (req, res) => {
        const email = req.body.email;
        const isPro = globalThis.registeredEmails.has(email.toLowerCase().trim());
        
        function base64url(obj) {
            return Buffer.from(JSON.stringify(obj))
                .toString('base64')
                .replace(/=/g, '')
                .replace(/\+/g, '-')
                .replace(/\//g, '_');
        }
        
        const payload = {
            user_id: "mock-user-id",
            email: email,
            subscription_sku: isPro ? "pro-annual" : null,
            subscription_status: isPro ? "active" : null,
            subscription_quantity: isPro ? 1 : 0,
            subscription_expiry: isPro ? "2100-01-01T00:00:00.000Z" : null,
            update_url: "",
            cancel_url: "",
            last_receipt_url: "",
            can_manage_subscription: false,
            feature_flags: [],
            banned: false,
            exp: 4102444800
        };
        
        const token = base64url({ alg: "none", typ: "JWT" }) + "." + base64url(payload) + ".mock_signature";
        
        res.json({
            accessToken: token,
            refreshToken: "mock-refresh-token",
            expiresAt: 4102444800000
        });
    });
